function validate([word]) {
  if (typeof word !== 'string' || word.length < 1 || word.length > 50) return 'word needs 1 to 50 characters.';
  if (!/^[a-zA-Z]+$/.test(word)) return 'word may contain only English letters.';
  return null;
}

reference:
function numberOfSpecialChars(word) {
  const seen = new Set(word);
  let count = 0;
  for (let code = 97; code <= 122; code++) {
    const lower = String.fromCharCode(code);
    const upper = lower.toUpperCase();
    if (seen.has(lower) && seen.has(upper)) {
      count++;
    }
  }
  return count;
}

