function numberOfSpecialChars(word) {
  const found = [];
  for (let i = 0; i < word.length; i++) {
    for (let j = 0; j < word.length; j++) {
      const a = word[i];
      const b = word[j];
      if (a >= 'a' && a <= 'z' && b === a.toUpperCase() && !found.includes(a)) found.push(a);
    }
  }
  return found.length;
}

