function generate(rand, size) {
  const n = size === 'large' ? 50 : 1 + Math.floor(rand() * 12);
  const letters = size === 'large' ? 26 : 1 + Math.floor(rand() * 5);
  const upperShare = rand();
  let word = '';
  for (let i = 0; i < n; i++) {
    const letter = String.fromCharCode(97 + Math.floor(rand() * letters));
    word += rand() < upperShare ? letter.toUpperCase() : letter;
  }
  return [word];
}
